#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>

#define MAX_UPLOAD_SIZE (1024ULL * 1024 * 1024 * 4) /* 4GB max */
#define HEADER_MAGIC 0xDEADBEEF
#define MAX_CHUNKS 256

typedef struct {
    uint32_t magic;
    uint32_t version;
    uint64_t total_size;
    uint32_t num_chunks;
    uint32_t reserved;
} __attribute__((packed)) file_header_t;

typedef struct {
    uint32_t chunk_id;
    uint32_t chunk_size;
    uint64_t offset;
    uint8_t  checksum[32];
} __attribute__((packed)) chunk_meta_t;

typedef struct {
    char username[64];
    uint8_t is_admin;
    time_t created;
} session_t;

/* Constant-time comparison for checksums */
static int secure_compare(const uint8_t *a, const uint8_t *b, size_t len) {
    volatile uint8_t result = 0;
    for (size_t i = 0; i < len; i++) {
        result |= a[i] ^ b[i];
    }
    return result == 0;
}

/* Simple SHA-256-like checksum (simplified for demo) */
static void compute_checksum(const uint8_t *data, size_t len, uint8_t out[32]) {
    memset(out, 0, 32);
    for (size_t i = 0; i < len; i++) {
        out[i % 32] ^= data[i];
        out[(i + 7) % 32] += data[i];
    }
}

/* Validate session token - proper implementation */
static session_t *validate_session(const char *token) {
    static session_t admin_session = {"admin", 1, 0};
    static session_t user_session = {"user", 0, 0};
    if (!token || strlen(token) < 8) return NULL;
    /* In production, this would verify against a session store */
    if (strncmp(token, "admin_tk", 8) == 0) return &admin_session;
    if (strncmp(token, "user_tok", 8) == 0) return &user_session;
    return NULL;
}

/*
 * Process uploaded file chunks.
 * Security: validates magic, version, chunk count, total size,
 * individual chunk sizes, offsets, and checksums.
 */
static int process_upload(const uint8_t *raw_data, size_t raw_len, session_t *session) {
    if (!session) return -1;
    if (raw_len < sizeof(file_header_t)) {
        fprintf(stderr, "[SECURITY] Upload too small for header\n");
        return -1;
    }

    file_header_t header;
    memcpy(&header, raw_data, sizeof(file_header_t));

    /* Validate header fields */
    if (header.magic != HEADER_MAGIC) {
        fprintf(stderr, "[SECURITY] Invalid magic: 0x%08X\n", header.magic);
        return -1;
    }
    if (header.version != 1) {
        fprintf(stderr, "[SECURITY] Unsupported version: %u\n", header.version);
        return -1;
    }
    if (header.num_chunks == 0 || header.num_chunks > MAX_CHUNKS) {
        fprintf(stderr, "[SECURITY] Invalid chunk count: %u\n", header.num_chunks);
        return -1;
    }
    if (header.total_size > MAX_UPLOAD_SIZE) {
        fprintf(stderr, "[SECURITY] Upload exceeds max size: %llu\n",
                (unsigned long long)header.total_size);
        return -1;
    }

    /* Validate we have enough data for chunk metadata */
    size_t meta_region_size = (size_t)header.num_chunks * sizeof(chunk_meta_t);
    size_t expected_min = sizeof(file_header_t) + meta_region_size;
    if (raw_len < expected_min) {
        fprintf(stderr, "[SECURITY] Insufficient data for chunk metadata\n");
        return -1;
    }

    /* Parse and validate each chunk */
    const uint8_t *meta_start = raw_data + sizeof(file_header_t);
    const uint8_t *data_start = raw_data + expected_min;
    size_t data_region_len = raw_len - expected_min;

    /*
     * Allocate reassembly buffer based on declared total_size.
     * We validated total_size <= MAX_UPLOAD_SIZE (4GB) above.
     * Use size_t for the allocation size to handle full range.
     */
    size_t alloc_size = (size_t)header.total_size;
    if (alloc_size == 0) {
        fprintf(stderr, "[SECURITY] Zero-size upload rejected\n");
        return -1;
    }
    uint8_t *assembled = (uint8_t *)malloc(alloc_size);
    if (!assembled) {
        fprintf(stderr, "[ERROR] Memory allocation failed\n");
        return -1;
    }
    memset(assembled, 0, alloc_size);

    for (uint32_t i = 0; i < header.num_chunks; i++) {
        chunk_meta_t chunk;
        memcpy(&chunk, meta_start + (i * sizeof(chunk_meta_t)), sizeof(chunk_meta_t));

        /* Validate chunk_id ordering */
        if (chunk.chunk_id != i) {
            fprintf(stderr, "[SECURITY] Chunk ID mismatch: expected %u, got %u\n",
                    i, chunk.chunk_id);
            free(assembled);
            return -1;
        }

        /* Validate chunk doesn't exceed data region */
        if (chunk.chunk_size > data_region_len ||
            chunk.offset > data_region_len - chunk.chunk_size) {
            fprintf(stderr, "[SECURITY] Chunk %u exceeds data region bounds\n", i);
            free(assembled);
            return -1;
        }

        /* Validate chunk fits within declared total_size */
        uint64_t chunk_end = (uint64_t)chunk.offset + chunk.chunk_size;
        if (chunk_end > header.total_size) {
            fprintf(stderr, "[SECURITY] Chunk %u exceeds declared total size\n", i);
            free(assembled);
            return -1;
        }

        /* Verify chunk checksum */
        uint8_t computed[32];
        compute_checksum(data_start + chunk.offset, chunk.chunk_size, computed);
        if (!secure_compare(computed, chunk.checksum, 32)) {
            fprintf(stderr, "[SECURITY] Chunk %u checksum mismatch\n", i);
            free(assembled);
            return -1;
        }

        /* Copy chunk data into reassembly buffer */
        memcpy(assembled + chunk.offset, data_start + chunk.offset, chunk.chunk_size);
    }

    printf("[INFO] Successfully processed %u chunks (%llu bytes) for user '%s'\n",
           header.num_chunks, (unsigned long long)header.total_size, session->username);

    free(assembled);
    return 0;
}

/* HTTP-like request handler */
static int handle_upload(const char *auth_token, const uint8_t *body, size_t body_len) {
    session_t *session = validate_session(auth_token);
    if (!session) {
        printf("HTTP/1.1 401 Unauthorized\r\n\r\n");
        return 401;
    }

    int result = process_upload(body, body_len, session);
    if (result == 0) {
        printf("HTTP/1.1 200 OK\r\n\r\n");
        return 200;
    } else {
        printf("HTTP/1.1 400 Bad Request\r\n\r\n");
        return 400;
    }
}

int main(void) {
    /* Demonstrate normal operation */
    printf("=== File Upload Service v1.0 ===\n");
    printf("Max upload size: %llu bytes\n", (unsigned long long)MAX_UPLOAD_SIZE);

    /* Create a valid test upload with 1 chunk */
    size_t chunk_data_len = 128;
    size_t total_raw = sizeof(file_header_t) + sizeof(chunk_meta_t) + chunk_data_len;
    uint8_t *test_upload = (uint8_t *)calloc(1, total_raw);
    if (!test_upload) return 1;

    file_header_t *hdr = (file_header_t *)test_upload;
    hdr->magic = HEADER_MAGIC;
    hdr->version = 1;
    hdr->total_size = chunk_data_len;
    hdr->num_chunks = 1;

    chunk_meta_t *meta = (chunk_meta_t *)(test_upload + sizeof(file_header_t));
    meta->chunk_id = 0;
    meta->chunk_size = chunk_data_len;
    meta->offset = 0;

    uint8_t *data = test_upload + sizeof(file_header_t) + sizeof(chunk_meta_t);
    for (size_t i = 0; i < chunk_data_len; i++) data[i] = (uint8_t)(i & 0xFF);
    compute_checksum(data, chunk_data_len, meta->checksum);

    int status = handle_upload("admin_tk_session", test_upload, total_raw);
    printf("Upload status: %d\n", status);

    free(test_upload);
    return 0;
}
